98	func newSummaryCmd() *cobra.Command {
99		opts := summaryOptions{Last: defaultSummarySessionLimit}
100	
101		cmd := &cobra.Command{
102			Use:   "summary [checkpoint-id]",
103			Short: "Browse source sessions with summaries and facets",
104			Args:  cobra.MaximumNArgs(1),
105			RunE: func(cmd *cobra.Command, args []string) error {
106				ctx := cmd.Context()
107				w := cmd.OutOrStdout()
108	
109				if checkDisabledGuard(ctx, w) {
110					return nil
111				}
112	
113				if !settings.IsSummarizeEnabled(ctx) {
114					fmt.Fprintln(w, "Summarization is required for summary browsing. Enable it in .entire/settings.json:")
115					fmt.Fprintln(w, `  { "strategy_options": { "summarize": { "enabled": true } } }`)
116					return nil
117				}
118	
119				if len(args) > 0 {
120					opts.CheckpointPrefix = args[0]
121				}
122	
123				return runSummary(ctx, w, opts)
124			},
125		}
126	
127		cmd.Flags().IntVar(&opts.Last, "last", opts.Last, "number of recent sessions to browse")
128		cmd.Flags().StringVar(&opts.Agent, "agent", "", "filter by agent name")
129		cmd.Flags().StringVar(&opts.Branch, "branch", "", "filter by branch")
130		cmd.Flags().BoolVar(&opts.Me, "me", false, "show only sessions for the active GitHub user")
131		cmd.Flags().BoolVar(&opts.OutputJSON, "json", false, "output sessions as JSON instead of launching the browser")
132		return cmd
133	}
