135	func runSummary(ctx context.Context, w io.Writer, opts summaryOptions) error {
136		rows, err := loadSummarySessions(ctx, opts)
137		if err != nil {
138			return err
139		}
140	
141		if opts.OutputJSON {
142			return renderSummaryJSON(w, rows)
143		}
144	
145		if IsAccessibleMode() {
146			renderSummaryText(w, rows)
147			return nil
148		}
149	
150		currentBranch := ""
151		if opts.CheckpointPrefix == "" {
152			if branch, err := GetCurrentBranch(ctx); err == nil {
153				currentBranch = branch
154			}
155		}
156	
157		// Load repo-scoped rows: the most recent sessions whose checkpoints
158		// are reachable from the default branch (independent view from current-branch rows).
159		repoRows := loadRepoSessions(ctx)
160	
161		return runSummaryTUI(ctx, rows, currentBranch, repoRows, generateForSession)
162	}
