164	func loadSummarySessions(ctx context.Context, opts summaryOptions) ([]insightsdb.SessionRow, error) {
165		worktreeRoot, err := paths.WorktreeRoot(ctx)
166		if err != nil {
167			return nil, fmt.Errorf("not in a git repository: %w", err)
168		}
169	
170		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
171		if err != nil {
172			return nil, fmt.Errorf("open insights cache: %w", err)
173		}
174		defer func() { _ = idb.Close() }()
175	
176		outputLimit := normalizedSummarySessionLimit(opts.Last)
177	
178		// Checkpoint prefix lookup: skip normal loading, query directly by prefix.
179		if opts.CheckpointPrefix != "" {
180			rows, err := idb.QueryByCheckpointPrefix(ctx, opts.CheckpointPrefix)
181			if err != nil {
182				return nil, fmt.Errorf("query by checkpoint: %w", err)
183			}
184			if len(rows) == 0 {
185				// Try refreshing cache in case the checkpoint hasn't been indexed yet.
186				if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
187					return nil, fmt.Errorf("refresh insights cache: %w", err)
188				}
189				rows, err = idb.QueryByCheckpointPrefix(ctx, opts.CheckpointPrefix)
190				if err != nil {
191					return nil, fmt.Errorf("query by checkpoint after refresh: %w", err)
192				}
193			}
194			if len(rows) == 0 {
195				return nil, fmt.Errorf("checkpoint not found: %s", opts.CheckpointPrefix)
196			}
197			return rows, nil
198		}
199	
200		rows, err := idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
201		if err != nil {
202			return nil, fmt.Errorf("query sessions: %w", err)
203		}
204		if len(rows) == 0 {
205			// First-run fallback: populate the cache if we have nothing local yet.
206			if err := summaryRefreshCacheIfStale(ctx, idb); err != nil {
207				return nil, fmt.Errorf("refresh insights cache: %w", err)
208			}
209			rows, err = idb.QueryLastNSessions(ctx, maxSummaryRecentSessions)
210			if err != nil {
211				return nil, fmt.Errorf("query sessions after refresh: %w", err)
212			}
213		}
214	
215		ownerID := ""
216		if opts.Me {
217			ownerID, err = githubidentity.ResolveUsername(ctx)
218			if err != nil {
219				return nil, fmt.Errorf("resolve github username: %w", err)
220			}
221		}
222	
223		hasCLIFilters := opts.Agent != "" || opts.Branch != "" || ownerID != ""
224	
225		filtered := make([]insightsdb.SessionRow, 0, len(rows))
226		for _, row := range rows {
227			if opts.Agent != "" && !strings.EqualFold(strings.TrimSpace(row.Agent), strings.TrimSpace(opts.Agent)) {
228				continue
229			}
230			if opts.Branch != "" && !strings.EqualFold(strings.TrimSpace(row.Branch), strings.TrimSpace(opts.Branch)) {
231				continue
232			}
233			if ownerID != "" && !strings.EqualFold(strings.TrimSpace(row.OwnerID), ownerID) {
234				continue
235			}
236			filtered = append(filtered, row)
237			// Only cap results when CLI filters or JSON output are in use.
238			// The TUI has its own branch filter, so it needs the full result set.
239			if hasCLIFilters && len(filtered) == outputLimit {
240				break
241			}
242		}
243	
244		return filtered, nil
245	}
