254	//nolint:musttag // nested external structs are part of the intended JSON payload
255	func renderSummaryJSON(w io.Writer, rows []insightsdb.SessionRow) error {
256		views := make([]summarySessionView, 0, len(rows))
257		for _, row := range rows {
258			views = append(views, summarySessionToView(row))
259		}
260	
261		enc := json.NewEncoder(w)
262		enc.SetIndent("", "  ")
263		if err := enc.Encode(views); err != nil {
264			return fmt.Errorf("encode summary sessions: %w", err)
265		}
266		return nil
267	}
