269	func renderSummaryText(w io.Writer, rows []insightsdb.SessionRow) {
270		s := termstyle.New(w)
271		fmt.Fprintln(w, s.Render(s.Bold, "Session Summary"))
272		if len(rows) == 0 {
273			fmt.Fprintln(w, "No sessions found.")
274			return
275		}
276	
277		for _, row := range rows {
278			fmt.Fprintf(w, "\n%s  %s  %s\n", row.CreatedAt.Format("2006-01-02 15:04"), row.Agent, row.SessionID)
279			if row.OwnerID != "" || row.OwnerName != "" || row.OwnerEmail != "" {
280				fmt.Fprintf(w, "Author: %s\n", fallbackText(row.OwnerID, "(unknown)"))
281				if row.OwnerName != "" {
282					fmt.Fprintf(w, "Author Name: %s\n", row.OwnerName)
283				}
284				if row.OwnerEmail != "" {
285					fmt.Fprintf(w, "Author Email: %s\n", row.OwnerEmail)
286				}
287			}
288			if row.Branch != "" {
289				fmt.Fprintf(w, "Branch: %s\n", row.Branch)
290			}
291			fmt.Fprintf(w, "Checkpoint: %s\n", row.CheckpointID)
292			fmt.Fprintf(w, "Summary: %s  Facets: %s\n", yesNo(row.HasSummary), yesNo(row.HasFacets))
293	
294			if row.HasSummary {
295				fmt.Fprintln(w, "Intent:")
296				fmt.Fprintf(w, "  %s\n", fallbackText(row.Intent, "No summary cached"))
297				fmt.Fprintln(w, "Outcome:")
298				fmt.Fprintf(w, "  %s\n", fallbackText(row.Outcome, "No summary cached"))
299				renderStringListSection(w, "Friction", row.Friction, "No friction recorded")
300				renderLearningSection(w, row.Learnings)
301				renderStringListSection(w, "Implementation Rationale", row.ImplementationRationale, "No implementation rationale recorded")
302				renderStringListSection(w, "Tradeoffs", row.Tradeoffs, "No tradeoffs recorded")
303				renderStringListSection(w, "Codebase Patterns", row.CodebasePatterns, "No codebase patterns recorded")
304			} else {
305				fmt.Fprintln(w, "No summary cached")
306			}
307	
308			renderFacetSections(w, row.Facets, row.HasFacets)
309		}
310	}
