322				fmt.Fprintf(w, "  - [%s] %s (%s)\n", learning.Scope, learning.Finding, learning.Path)
323				continue
324			}
325			fmt.Fprintf(w, "  - [%s] %s\n", learning.Scope, learning.Finding)
326		}
