450	// buildRepoCheckpointSet returns the set of checkpoint IDs reachable from the
451	// default branch. Returns nil if the default branch can't be resolved (the TUI
452	// will treat nil as "repo filter unavailable" and show all sessions).
453	func buildRepoCheckpointSet(ctx context.Context) map[string]struct{} {
454		repo, err := openRepository(ctx)
455		if err != nil {
456			return nil
457		}
458		_, defaultBranchHash, err := resolveMemoryLoopDefaultBranch(repo)
459		if err != nil {
460			return nil
461		}
462		ids, err := listReachableCheckpointIDs(ctx, repo, defaultBranchHash)
463		if err != nil {
464			return nil
465		}
466		return ids
467	}
