469	// generateForSession generates summary and facets for a single session on demand.
470	// It opens its own database connection and checkpoint store.
471	func generateForSession(ctx context.Context, row insightsdb.SessionRow) (insightsdb.SessionRow, error) {
472		repo, err := openRepository(ctx)
473		if err != nil {
474			return row, fmt.Errorf("open repository: %w", err)
475		}
476		store := checkpoint.NewGitStore(repo)
477	
478		cpID, err := checkpointid.NewCheckpointID(row.CheckpointID)
479		if err != nil {
480			return row, fmt.Errorf("invalid checkpoint ID: %w", err)
481		}
482	
483		content, err := store.ReadSessionContent(ctx, cpID, row.SessionIndex)
484		if err != nil {
485			return row, fmt.Errorf("read session content: %w", err)
486		}
487		if len(content.Transcript) == 0 {
488			return row, fmt.Errorf("empty transcript for checkpoint %s", row.CheckpointID)
489		}
490	
491		condensed, err := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
492		if err != nil {
493			return row, fmt.Errorf("condense transcript: %w", err)
494		}
495		if len(condensed) == 0 {
496			return row, fmt.Errorf("condensed transcript empty for checkpoint %s", row.CheckpointID)
497		}
498	
499		input := summarize.Input{
500			Transcript:   condensed,
501			FilesTouched: row.FilesTouched,
502		}
503	
504		// Generate summary.
505		gen := &summarize.ClaudeGenerator{}
506		summary, genErr := gen.Generate(ctx, input)
507		if genErr != nil {
508			logging.Debug(ctx, "generateForSession: summary generation failed",
509				"checkpoint_id", row.CheckpointID, "error", genErr)
510		}
511		if summary != nil {
512			content.Metadata.Summary = summary
513			row = metadataToSessionRow(row.CheckpointID, row.SessionIndex, &content.Metadata)
514		}
515	
516		// Extract facets.
517		formatted := summarize.FormatCondensedTranscript(input)
518		extractor := &facets.Extractor{Runner: &llmcli.Runner{}}
519		facetResult, _, extractErr := extractor.Extract(ctx, formatted)
520		if extractErr != nil {
521			logging.Debug(ctx, "generateForSession: facet extraction failed",
522				"checkpoint_id", row.CheckpointID, "error", extractErr)
523		}
524		if facetResult != nil {
525			row.Facets = *facetResult
526			row.HasFacets = true
527		}
528	
529		// Persist to database.
530		worktreeRoot, err := paths.WorktreeRoot(ctx)
531		if err != nil {
532			return row, fmt.Errorf("find worktree root: %w", err)
533		}
534		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
535		if err != nil {
536			return row, fmt.Errorf("open insights db: %w", err)
537		}
538		defer func() { _ = idb.Close() }()
539	
540		if row.HasSummary {
541			if updateErr := idb.UpdateSessionSummary(ctx, row); updateErr != nil {
542				return row, fmt.Errorf("save summary: %w", updateErr)
543			}
544		}
545		if row.HasFacets {
546			if updateErr := idb.UpdateSessionFacets(ctx, row); updateErr != nil {
547				return row, fmt.Errorf("save facets: %w", updateErr)
548			}
549		}
550	
551		// Return partial success even if one phase failed.
552		if genErr != nil && extractErr != nil {
553			return row, fmt.Errorf("summary: %w; facets: %w", genErr, extractErr)
554		}
555		return row, nil
556	}
