13	// renderMetadataHeader renders the fixed metadata header with two side-by-side boxes.
14	func renderMetadataHeader(s styles, row insightsdb.SessionRow, width int) string {
15		tokensWidth := 14
16		sessionWidth := max(0, width-tokensWidth-3) // gap between boxes
17	
18		// SESSION box content — two lines for readability
19		sep := s.render(s.dim, " · ")
20	
21		var line1 []string
22		if row.CheckpointID != "" {
23			line1 = append(line1, s.render(s.detailLabel, "checkpoint:")+s.render(s.detailValue, " "+row.CheckpointID))
24		}
25		if row.Agent != "" {
26			line1 = append(line1, s.render(s.detailLabel, "agent:")+s.render(s.detailValue, " "+row.Agent))
27		}
28		author := row.OwnerName
29		if author == "" {
30			author = row.OwnerID
31		}
32		if author != "" {
33			line1 = append(line1, s.render(s.detailLabel, "author:")+s.render(s.detailValue, " "+author))
34		}
35	
36		var line2 []string
37		if row.Branch != "" {
38			line2 = append(line2, s.render(s.detailLabel, "branch:")+s.render(s.detailValue, " "+row.Branch))
39		}
40		if row.Model != "" {
41			line2 = append(line2, s.render(s.detailLabel, "model:")+s.render(s.detailValue, " "+row.Model))
42		}
43		line2 = append(line2, s.render(s.detailLabel, "turns:")+s.render(s.detailValue, " "+strconv.Itoa(row.TurnCount)))
44	
45		var lines []string
46		if len(line1) > 0 {
47			lines = append(lines, strings.Join(line1, sep))
48		}
49		if len(line2) > 0 {
50			lines = append(lines, strings.Join(line2, sep))
51		}
52		sessionContent := strings.Join(lines, "\n")
53		sessionBox := s.renderBox("SESSION", sessionContent, sessionWidth)
54	
55		// TOKENS box content
56		tokensContent := s.render(s.detailValue, formatTokensForDetail(row.TotalTokens))
57		tokensBox := s.renderBox("TOKENS", tokensContent, tokensWidth)
58	
59		return lipgloss.JoinHorizontal(lipgloss.Top, sessionBox, " ", tokensBox)
60	}
