62	// renderDetailContent renders the scrollable detail content with bordered boxes.
63	func renderDetailContent(s styles, row insightsdb.SessionRow, width int) string {
64		var sections []string
65	
66		// Box 1: SUMMARY (intent, outcome, scores, stats)
67		if box := renderSummaryBox(s, row, width); box != "" {
68			sections = append(sections, box)
69		}
70	
71		// Box 2: CODE (files, tools, rationale, tradeoffs, patterns)
72		if box := renderCodeBox(s, row, width); box != "" {
73			sections = append(sections, box)
74		}
75	
76		// Box 3: LEARNINGS
77		if row.HasSummary && len(row.Learnings) > 0 {
78			sections = append(sections, renderLearningsBox(s, row, width))
79		}
80	
81		// Box 4: SIGNALS (friction + all facets with evidence)
82		if row.HasFacets || (row.HasSummary && len(row.Friction) > 0) {
83			if box := renderSignalsBox(s, row, width); box != "" {
84				sections = append(sections, box)
85			}
86		}
87	
88		if len(sections) == 0 {
89			return s.render(s.emptyState, "  No summary or insights cached. Press g to generate.")
90		}
91	
92		return strings.Join(sections, "\n\n")
93	}
