95	// renderSubSection renders a dim uppercase sub-section header followed by content lines.
96	// Returns nil if lines is empty. Prepends a blank line separator when appending to
97	// existing content (caller passes current length so first sub-section has no leading gap).
98	func renderSubSection(s styles, currentLen int, title string, lines []string) []string {
99		if len(lines) == 0 {
100			return nil
101		}
102		var result []string
103		if currentLen > 0 {
104			result = append(result, "") // blank line separator between sub-sections
105		}
106		result = append(result, s.render(s.dim, strings.ToUpper(title)))
107		result = append(result, lines...)
108		return result
109	}
