111	func renderCodeBox(s styles, row insightsdb.SessionRow, width int) string {
112		var allLines []string
113	
114		// Files touched
115		var fileLines []string
116		for _, f := range row.FilesTouched {
117			fileLines = append(fileLines, s.render(s.bullet, "• ")+f)
118		}
119		allLines = append(allLines, renderSubSection(s, len(allLines), "Files Touched", fileLines)...)
120	
121		// Tool usage — sorted by count descending, compact single line
122		if len(row.ToolCounts) > 0 {
123			type toolCount struct {
124				name  string
125				count int
126			}
127			sorted := make([]toolCount, 0, len(row.ToolCounts))
128			for name, count := range row.ToolCounts {
129				sorted = append(sorted, toolCount{name, count})
130			}
131			sort.Slice(sorted, func(i, j int) bool {
132				return sorted[i].count > sorted[j].count
133			})
134			var parts []string
135			for _, tc := range sorted {
136				parts = append(parts, fmt.Sprintf("%s (%d)", tc.name, tc.count))
137			}
138			toolLine := s.render(s.bullet, "• ") + strings.Join(parts, " · ")
139			allLines = append(allLines, renderSubSection(s, len(allLines), "Tool Usage", []string{toolLine})...)
140		}
141	
142		// Implementation rationale
143		var rationaleLines []string
144		for _, item := range row.ImplementationRationale {
145			rationaleLines = append(rationaleLines, s.render(s.bullet, "• ")+item)
146		}
147		allLines = append(allLines, renderSubSection(s, len(allLines), "Implementation Rationale", rationaleLines)...)
148	
149		// Tradeoffs
150		var tradeoffLines []string
151		for _, item := range row.Tradeoffs {
152			tradeoffLines = append(tradeoffLines, s.render(s.bullet, "• ")+item)
153		}
154		allLines = append(allLines, renderSubSection(s, len(allLines), "Tradeoffs", tradeoffLines)...)
155	
156		// Codebase patterns
157		var patternLines []string
158		for _, item := range row.CodebasePatterns {
159			patternLines = append(patternLines, s.render(s.bullet, "• ")+item)
160		}
161		allLines = append(allLines, renderSubSection(s, len(allLines), "Codebase Patterns", patternLines)...)
162	
163		if len(allLines) == 0 {
164			return ""
165		}
166		return s.renderBox("CODE", strings.Join(allLines, "\n"), width)
167	}
