169	func renderSummaryBox(s styles, row insightsdb.SessionRow, width int) string {
170		var lines []string
171		if row.Intent != "" {
172			lines = append(lines, s.render(s.detailLabel, "Intent: ")+s.render(s.detailValue, row.Intent))
173		}
174		if row.Outcome != "" {
175			lines = append(lines, s.render(s.detailLabel, "Outcome: ")+s.render(s.detailValue, row.Outcome))
176		}
177	
178		// Score line — add spacing after intent/outcome
179		if row.OverallScore > 0 {
180			if len(lines) > 0 {
181				lines = append(lines, "")
182			}
183			scoreLine := s.render(s.detailLabel, "Score: ") +
184				s.render(s.detailValue, fmt.Sprintf("%.1f", row.OverallScore)) + " " +
185				s.render(s.dim, fmt.Sprintf("— tok:%.1f · 1st:%.1f · fric:%.1f · foc:%.1f",
186					row.ScoreTokenEff, row.ScoreFirstPass, row.ScoreFriction, row.ScoreFocus))
187			lines = append(lines, scoreLine)
188		}
189	
190		// Stats line — add spacing if following intent/outcome without a score line
191		hasStats := row.InputTokens > 0 || row.OutputTokens > 0 || row.APICallCount > 0 || row.DurationMs > 0
192		if hasStats {
193			if len(lines) > 0 && row.OverallScore == 0 {
194				lines = append(lines, "")
195			}
196			var parts []string
197			parts = append(parts, s.render(s.detailLabel, "Tokens: ")+
198				s.render(s.detailValue, formatTokensForDetail(row.InputTokens)+" in · "+
199					formatTokensForDetail(row.CacheTokens)+" cache · "+
200					formatTokensForDetail(row.OutputTokens)+" out"))
201			if row.APICallCount > 0 {
202				parts = append(parts, s.render(s.detailLabel, "API: ")+
203					s.render(s.detailValue, fmt.Sprintf("%d calls", row.APICallCount)))
204			}
205			if row.DurationMs > 0 {
206				parts = append(parts, s.render(s.detailLabel, "Time: ")+
207					s.render(s.detailValue, formatDuration(row.DurationMs)))
208			}
209			if row.AgentPct > 0 {
210				parts = append(parts, s.render(s.detailLabel, "Agent: ")+
211					s.render(s.detailValue, fmt.Sprintf("%d%%", int(row.AgentPct))))
212			}
213			lines = append(lines, strings.Join(parts, "   "))
214		}
215	
216		if len(lines) == 0 {
217			return ""
218		}
219		return s.renderBox("SUMMARY", strings.Join(lines, "\n"), width)
220	}
