259				fmt.Sprintf("%s (×%d)", item.Description, item.Count))
260			loopLines = append(loopLines, renderEvidence(s, item.Evidence)...)
261		}
262		allLines = append(allLines, renderSubSection(s, len(allLines), "Failure Loops", loopLines)...)
263	
264		// Repeated instructions
265		var repeatLines []string
266		for _, item := range row.Facets.RepeatedUserInstructions {
267			repeatLines = append(repeatLines, s.render(s.bullet, "• ")+item.Instruction)
268			repeatLines = append(repeatLines, renderEvidence(s, item.Evidence)...)
269		}
270		allLines = append(allLines, renderSubSection(s, len(allLines), "Repeated Instructions", repeatLines)...)
271	
272		// Missing context
273		var ctxLines []string
274		for _, item := range row.Facets.MissingContext {
275			ctxLines = append(ctxLines, s.render(s.bullet, "• ")+item.Item)
276			ctxLines = append(ctxLines, renderEvidence(s, item.Evidence)...)
277		}
278		allLines = append(allLines, renderSubSection(s, len(allLines), "Missing Context", ctxLines)...)
279	
280		// Skill signals
281		var skillLines []string
282		for _, item := range row.Facets.SkillSignals {
