287			if item.MissingInstruction != "" {
288				skillLines = append(skillLines, s.render(s.dim, "  missing: "+item.MissingInstruction))
289			}
290		}
291		allLines = append(allLines, renderSubSection(s, len(allLines), "Skill Signals", skillLines)...)
292	
293		// Review-derived rules
294		var ruleLines []string
295		for _, item := range row.Facets.ReviewDerivedRules {
296			ruleLines = append(ruleLines, s.render(s.bullet, "• ")+item.Rule)
297			if item.SourceKind != "" || item.Strength != "" {
298				ruleLines = append(ruleLines, s.render(s.dim,
299					"  source: "+item.SourceKind+" · strength: "+item.Strength))
300			}
301			ruleLines = append(ruleLines, renderEvidence(s, item.Evidence)...)
302			if item.WhyReusable != "" {
303				ruleLines = append(ruleLines, s.render(s.dim, "  reusable: "+item.WhyReusable))
304			}
305		}
306		allLines = append(allLines, renderSubSection(s, len(allLines), "Review Rules", ruleLines)...)
307	
308		// Repo gotchas
309		var gotchaLines []string
310		for _, item := range row.Facets.RepoGotchas {
311			gotchaLines = append(gotchaLines, s.render(s.bullet, "• ")+item)
312		}
313		allLines = append(allLines, renderSubSection(s, len(allLines), "Repo Gotchas", gotchaLines)...)
314	
315		// Workflow gaps
316		var gapLines []string
317		for _, item := range row.Facets.WorkflowGaps {
318			gapLines = append(gapLines, s.render(s.bullet, "• ")+item)
319		}
320		allLines = append(allLines, renderSubSection(s, len(allLines), "Workflow Gaps", gapLines)...)
321	
322		if len(allLines) == 0 {
323			return ""
324		}
325		return s.renderBox("SIGNALS", strings.Join(allLines, "\n"), width)
326	}
