328	func formatTokensForDetail(tokens int) string {
329		switch {
330		case tokens >= 1_000_000:
331			return fmt.Sprintf("%.1fM", float64(tokens)/1_000_000)
332		case tokens >= 1_000:
333			return fmt.Sprintf("%.1fk", float64(tokens)/1_000)
334		default:
335			return strconv.Itoa(tokens)
336		}
337	}
338	
339	func formatDuration(ms int64) string {
340		totalSec := ms / 1000
341		switch {
342		case totalSec >= 3600:
343			h := totalSec / 3600
344			m := (totalSec % 3600) / 60
345			return fmt.Sprintf("%dh %dm", h, m)
346		case totalSec >= 60:
347			m := totalSec / 60
348			s := totalSec % 60
349			return fmt.Sprintf("%dm %ds", m, s)
350		default:
351			return fmt.Sprintf("%ds", totalSec)
352		}
353	}
