63	// GetBranchTip returns the stored branch tip hash from cache_meta,
64	// or an empty string if it has not been set yet.
65	func (idb *InsightsDB) GetBranchTip(ctx context.Context) (string, error) {
66		var tip string
67		err := idb.db.QueryRowContext(ctx,
68			"SELECT value FROM cache_meta WHERE key = ?",
69			"branch_tip",
70		).Scan(&tip)
71		if err == sql.ErrNoRows {
72			return "", nil
73		}
74		if err != nil {
75			return "", fmt.Errorf("get branch tip: %w", err)
76		}
77		return tip, nil
78	}
79	
80	// SetBranchTip stores the branch tip hash in cache_meta.
81	// Overwrites any previously stored value.
82	func (idb *InsightsDB) SetBranchTip(ctx context.Context, tip string) error {
83		_, err := idb.db.ExecContext(ctx,
84			"INSERT OR REPLACE INTO cache_meta (key, value) VALUES (?, ?)",
85			"branch_tip",
86			tip,
87		)
88		if err != nil {
89			return fmt.Errorf("set branch tip: %w", err)
90		}
91		return nil
92	}
