94	// GetContentFingerprint returns a lightweight fingerprint of the insightsdb
95	// data state, based on row counts of key tables. This changes when facets
96	// are backfilled or new tool_calls are ingested, even if the branch tip
97	// hasn't changed.
98	func (idb *InsightsDB) GetContentFingerprint(ctx context.Context) (string, error) {
99		var fingerprint string
100		err := idb.db.QueryRowContext(ctx, `
101			SELECT
102				(SELECT COUNT(*) FROM sessions) || ':' ||
103				(SELECT COUNT(*) FROM skill_signals) || ':' ||
104				(SELECT COUNT(*) FROM review_rule_signals) || ':' ||
105				(SELECT COUNT(*) FROM tool_calls WHERE tool_name = 'Skill') || ':' ||
106				(SELECT COUNT(*) FROM sessions WHERE has_facets = 1)
107		`).Scan(&fingerprint)
108		if err != nil {
109			return "", fmt.Errorf("get content fingerprint: %w", err)
110		}
111		return fingerprint, nil
112	}
