114	// HasCheckpoint returns true if any session for the given checkpoint ID
115	// is already present in the sessions table.
116	func (idb *InsightsDB) HasCheckpoint(ctx context.Context, checkpointID string) (bool, error) {
117		var count int
118		err := idb.db.QueryRowContext(ctx,
119			"SELECT COUNT(*) FROM sessions WHERE checkpoint_id = ?",
120			checkpointID,
121		).Scan(&count)
122		if err != nil {
123			return false, fmt.Errorf("check checkpoint existence: %w", err)
