128	// InsertSession inserts a session and all its denormalized data into the cache.
129	// The insert is performed inside a single transaction so the cache remains
130	// consistent even if the caller is interrupted mid-insert.
131	func (idb *InsightsDB) InsertSession(ctx context.Context, row SessionRow) error {
132		tx, err := idb.db.BeginTx(ctx, nil)
133		if err != nil {
134			return fmt.Errorf("begin transaction: %w", err)
135		}
136		defer func() {
137			if err != nil {
138				_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
139			}
140		}()
141	
142		if err = insertSessionRow(ctx, tx, row); err != nil {
143			return err
144		}
145		if err = insertFilesTouched(ctx, tx, row); err != nil {
146			return err
147		}
148		if err = insertFriction(ctx, tx, row); err != nil {
149			return err
150		}
151		if err = insertLearnings(ctx, tx, row); err != nil {
152			return err
153		}
154		if err = insertSummarySignals(ctx, tx, row); err != nil {
155			return err
156		}
157		if err = insertToolCalls(ctx, tx, row); err != nil {
158			return err
159		}
160		if err = insertFacets(ctx, tx, row); err != nil {
161			return err
162		}
163	
164		if err = tx.Commit(); err != nil {
165			return fmt.Errorf("commit transaction: %w", err)
166		}
167		return nil
168	}
