170	func insertSessionRow(ctx context.Context, tx *sql.Tx, row SessionRow) error {
171		hasSummary := 0
172		if row.HasSummary {
173			hasSummary = 1
174		}
175		hasFacets := 0
176		if row.HasFacets || !isEmptyFacets(row.Facets) {
177			hasFacets = 1
178		}
179		_, err := tx.ExecContext(ctx, `
180			INSERT INTO sessions (
181				checkpoint_id, session_id, session_index,
182				agent, model, branch, owner_name, owner_id, owner_email, created_at,
183				input_tokens, cache_tokens, output_tokens, total_tokens,
184				api_call_count, duration_ms, turn_count,
185				intent, outcome, agent_percentage,
186				overall_score, score_token_efficiency, score_first_pass,
187				score_friction, score_focus, has_summary, has_facets
188			) VALUES (
189				?, ?, ?,
190				?, ?, ?, ?, ?, ?, ?,
191				?, ?, ?, ?,
192				?, ?, ?,
193				?, ?, ?,
194				?, ?, ?,
195				?, ?, ?, ?
196			)`,
197			row.CheckpointID, row.SessionID, row.SessionIndex,
198			nullableString(row.Agent), nullableString(row.Model), nullableString(row.Branch),
199			nullableString(row.OwnerName), nullableString(row.OwnerID), nullableString(row.OwnerEmail),
200			row.CreatedAt.UTC().Format(time.RFC3339),
201			row.InputTokens, row.CacheTokens, row.OutputTokens, row.TotalTokens,
202			row.APICallCount, row.DurationMs, row.TurnCount,
203			nullableString(row.Intent), nullableString(row.Outcome), row.AgentPct,
204			row.OverallScore, row.ScoreTokenEff,
205			row.ScoreFirstPass, row.ScoreFriction,
206			row.ScoreFocus, hasSummary, hasFacets,
207		)
208		if err != nil {
209			return fmt.Errorf("insert session row: %w", err)
210		}
211		return nil
212	}
