341	// UpdateSessionSummary updates an existing session row with summary-derived data
342	// (intent, outcome, scores, friction, learnings, explanatory insight arrays)
343	// and sets has_summary = 1.
344	func (idb *InsightsDB) UpdateSessionSummary(ctx context.Context, row SessionRow) error {
345		tx, err := idb.db.BeginTx(ctx, nil)
346		if err != nil {
347			return fmt.Errorf("begin transaction: %w", err)
348		}
349		defer func() {
350			if err != nil {
351				_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
352			}
353		}()
354	
355		_, err = tx.ExecContext(ctx, `
356			UPDATE sessions SET
357				intent = ?, outcome = ?,
358				overall_score = ?, score_token_efficiency = ?, score_first_pass = ?,
359				score_friction = ?, score_focus = ?, has_summary = 1
360			WHERE checkpoint_id = ? AND session_index = ?`,
361			nullableString(row.Intent), nullableString(row.Outcome),
362			row.OverallScore, row.ScoreTokenEff, row.ScoreFirstPass,
363			row.ScoreFriction, row.ScoreFocus,
364			row.CheckpointID, row.SessionIndex,
365		)
366		if err != nil {
367			return fmt.Errorf("update session summary: %w", err)
368		}
369	
370		// Delete old summary-derived rows and re-insert.
371		for _, table := range []string{
372			"friction",
373			"learnings",
374			"implementation_rationale",
375			"tradeoffs",
376			"codebase_patterns",
377		} {
378			if _, err = tx.ExecContext(ctx,
379				"DELETE FROM "+table+" WHERE checkpoint_id = ? AND session_index = ?", //nolint:gosec // table name is hardcoded
380				row.CheckpointID, row.SessionIndex,
381			); err != nil {
382				return fmt.Errorf("delete old %s: %w", table, err)
383			}
384		}
385	
386		if err = insertFriction(ctx, tx, row); err != nil {
387			return err
388		}
389		if err = insertLearnings(ctx, tx, row); err != nil {
390			return err
391		}
392		if err = insertSummarySignals(ctx, tx, row); err != nil {
393			return err
394		}
395	
396		if err = tx.Commit(); err != nil {
397			return fmt.Errorf("commit transaction: %w", err)
398		}
399		return nil
400	}
