231		// First, try to find in committed checkpoints by checkpoint ID prefix
232		committed, err := listCommittedForExplain(ctx, v1Store, v2Store, preferCheckpointsV2)
233		if err != nil {
234			return fmt.Errorf("failed to list checkpoints: %w", err)
235		}
236	
237		// Collect all matching checkpoint IDs to detect ambiguity
238		var matches []id.CheckpointID
239		for _, info := range committed {
240			if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
241				matches = append(matches, info.CheckpointID)
242			}
243		}
244	
245		var fullCheckpointID id.CheckpointID
246		switch len(matches) {
247		case 0:
248			// Not found in committed, try temporary checkpoints by git SHA
249			if generate {
250				return fmt.Errorf("cannot generate summary for temporary checkpoint %s (only committed checkpoints supported)", checkpointIDPrefix)
251			}
252			output, found := explainTemporaryCheckpoint(ctx, w, repo, v1Store, checkpointIDPrefix, verbose, full, rawTranscript)
253			if found {
254				outputExplainContent(w, output, noPager)
255				return nil
256			}
257			// If output is non-empty, it contains an error message (e.g., ambiguous prefix)
258			if output != "" {
259				return errors.New(output)
260			}
261			return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
262		case 1:
263			fullCheckpointID = matches[0]
264		default:
265			// Ambiguous prefix - show up to 5 examples
266			examples := make([]string, 0, 5)
267			for i := 0; i < len(matches) && i < 5; i++ {
268				examples = append(examples, matches[i].String())
269			}
270			return fmt.Errorf("ambiguous checkpoint prefix %q matches %d checkpoints: %s", checkpointIDPrefix, len(matches), strings.Join(examples, ", "))
271		}
272	
273		// Resolve store and load checkpoint summary with v2 -> v1 fallback.
274		resolvedReader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, fullCheckpointID, v1Store, v2Store, preferCheckpointsV2)
