371		parts = append(parts, "j/k navigate")
372		parts = append(parts, "pgup/dn scroll")
373		parts = append(parts, "1 time")
374		parts = append(parts, "2 branch")
375		parts = append(parts, "←→ page")
376		if m.generateFn != nil {
377			parts = append(parts, "g generate")
378		}
379		parts = append(parts, "q quit")
380		status := strings.Join(parts, "  ")
381	
382		if m.genStatus != "" {
383			style := m.styles.filterActive
384			if strings.HasPrefix(m.genStatus, "Error:") {
385				style = m.styles.errorText
386			}
387			status = m.styles.render(style, m.genStatus) + "  " + status
388		}
389	
390		return m.styles.render(m.styles.statusBar, status)
391	}
392	
393	// --- Layout helpers ---
394	
395	func (m rootModel) listWidth() int {
396		return max(30, m.width*30/100)
397	}
398	
399	func (m rootModel) detailWidth() int {
400		return max(30, m.width-m.listWidth()-1)
401	}
402	
403	func (m rootModel) contentHeight() int {
404		return max(5, m.height-verticalChrome)
405	}
406	
407	// --- Data management ---
408	
409	func (m *rootModel) updateRowData(updated insightsdb.SessionRow) {
410		for i, row := range m.branchRows {
411			if row.SessionID == updated.SessionID {
412				m.branchRows[i] = updated
413				break
414			}
415		}
416		for i, row := range m.repoRows {
417			if row.SessionID == updated.SessionID {
418				m.repoRows[i] = updated
419				break
420			}
421		}
422		for i, row := range m.filteredRows {
423			if row.SessionID == updated.SessionID {
424				m.filteredRows[i] = updated
425				break
426			}
427		}
428	}
429	
430	func (m *rootModel) rebuildFilteredRows() {
431		m.filteredRows = m.applyFilter()
432		m.paginator.PerPage = m.pageSize
433		totalPages := m.paginator.SetTotalPages(len(m.filteredRows))
434		if totalPages == 0 {
435			m.paginator.TotalPages = 1
436		}
437		if m.paginator.Page >= m.paginator.TotalPages {
438			m.paginator.Page = max(0, m.paginator.TotalPages-1)
439		}
440		if m.paginator.Page < 0 {
441			m.paginator.Page = 0
442		}
443		if m.cursor >= len(m.currentPageRows()) {
444			m.cursor = max(0, len(m.currentPageRows())-1)
445		}
446	}
447	
448	func (m rootModel) applyFilter() []insightsdb.SessionRow {
449		// Select source rows based on branch filter scope.
450		var source []insightsdb.SessionRow
451		switch m.branchFilter {
452		case filterCurrentBranch:
453			source = m.branchRows
454		case filterRepo:
455			source = m.repoRows
456		}
457	
458		filtered := make([]insightsdb.SessionRow, 0, len(source))
459		now := time.Now()
460		for _, row := range source {
461			// Time filter
462			switch m.timeFilter {
463			case timeFilter24h:
464				if now.Sub(row.CreatedAt) > 24*time.Hour {
465					continue
466				}
467			case timeFilter7d:
468				if now.Sub(row.CreatedAt) > 7*24*time.Hour {
469					continue
470				}
471			case timeFilter30d:
472				if now.Sub(row.CreatedAt) > 30*24*time.Hour {
473					continue
474				}
475			case timeFilterAll:
476				// no time filtering
477			}
478	
479			// Current-branch view still filters by branch name.
480			if m.branchFilter == filterCurrentBranch && m.currentBranch != "" && row.Branch != m.currentBranch {
481				continue
482			}
483	
484			filtered = append(filtered, row)
485		}
486		return filtered
487	}
488	
489	func (m rootModel) currentPageRows() []insightsdb.SessionRow {
490		if len(m.filteredRows) == 0 {
491			return nil
492		}
493		start, end := m.paginator.GetSliceBounds(len(m.filteredRows))
494		if start >= len(m.filteredRows) {
495			return nil
496		}
497		if end > len(m.filteredRows) {
498			end = len(m.filteredRows)
499		}
500		return m.filteredRows[start:end]
501	}
502	
503	func (m rootModel) selectedRow() *insightsdb.SessionRow {
504		rows := m.currentPageRows()
505		if m.cursor < 0 || m.cursor >= len(rows) {
506			return nil
507		}
508		return &rows[m.cursor]
509	}
510	
511	// --- Navigation ---
512	
513	func (m *rootModel) moveCursor(delta int) {
514		pageRows := m.currentPageRows()
515		if len(pageRows) == 0 {
516			return
517		}
518		m.cursor += delta
519		if m.cursor < 0 {
520			m.cursor = 0
521		}
522		if m.cursor >= len(pageRows) {
523			m.cursor = len(pageRows) - 1
524		}
525		m.genStatus = "" // clear status on navigation
526		m.updateDetailViewport()
527	}
528	
529	func (m *rootModel) cycleTime() {
530		m.timeFilter = (m.timeFilter + 1) % 4
531		m.paginator.Page = 0
532		m.cursor = 0
533		m.genStatus = ""
534		m.rebuildFilteredRows()
535		m.updateDetailViewport()
536	}
537	
538	func (m *rootModel) cycleBranch() {
539		m.branchFilter = (m.branchFilter + 1) % 2
540		m.paginator.Page = 0
541		m.cursor = 0
542		m.genStatus = ""
543		m.rebuildFilteredRows()
544		m.updateDetailViewport()
545	}
546	
547	func (m *rootModel) nextPage() {
548		if m.paginator.OnLastPage() {
549			return
550		}
551		m.paginator.NextPage()
552		m.cursor = 0
553		m.genStatus = ""
554		m.updateDetailViewport()
555	}
556	
557	func (m *rootModel) prevPage() {
558		if m.paginator.OnFirstPage() {
559			return
560		}
561		m.paginator.PrevPage()
562		m.cursor = 0
563		m.genStatus = ""
564		m.updateDetailViewport()
565	}
566	
567	func (m *rootModel) updateDetailViewport() {
568		row := m.selectedRow()
569		if row == nil {
570			m.detailVP.SetContent("")
571			return
572		}
573		content := renderDetailContent(m.styles, *row, m.detailWidth())
574		m.detailVP.SetContent(content)
575	}
576	
577	func (m *rootModel) resize(width, height int) {
578		selectedSessionID := ""
579		if selected := m.selectedRow(); selected != nil {
580			selectedSessionID = selected.SessionID
581		}
582	
583		m.width = width
584		m.height = height
585	
586		contentHeight := m.contentHeight()
587		listHeight := contentHeight - 2 // header + separator
588		m.pageSize = max(1, listHeight)
589	
590		// Detail viewport: subtract detail header (1) + separator (1) + metadata header (~3) + blank line (1) = 6
591		vp := viewport.New(m.detailWidth(), max(3, contentHeight-6))
592		vp.MouseWheelEnabled = false
593		m.detailVP = vp
594	
595		m.rebuildFilteredRows()
596		m.restoreSelection(selectedSessionID)
597		m.updateDetailViewport()
598	}
599	
600	func (m *rootModel) restoreSelection(sessionID string) {
601		if sessionID == "" || len(m.filteredRows) == 0 {
602			return
603		}
604	
605		for idx, row := range m.filteredRows {
606			if row.SessionID != sessionID {
607				continue
608			}
609	
610			m.paginator.Page = idx / m.pageSize
611			cursor := idx % m.pageSize
612			pageRows := m.currentPageRows()
613			if len(pageRows) > 0 && cursor >= len(pageRows) {
614				cursor = len(pageRows) - 1
615			}
616			m.cursor = cursor
617			return
618		}
619	}
